75	function makeConflictResolver(
76	  model: string,
77	  maxTurns = 10,
78	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
79	  return (prompt, cwd, env) =>
80	    new Promise((resolve) => {
81	      const child = spawn(
82	        "claude",
83	        [
84	          "-p", prompt,
85	          "--model", model,
86	          "--max-turns", String(maxTurns),
87	          "--output-format", "stream-json",
88	          "--verbose",
89	          "--dangerously-skip-permissions",
90	        ],
91	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
92	      );
93	      child.stdout.pipe(process.stdout);
94	      child.stderr.pipe(process.stderr);
95	      child.on("close", (code) => resolve(code === 0));
96	      child.on("error", () => resolve(false));
