318	  async function buildAndSubmitExecutor(opts: {
319	    task: Task;
320	    featureId: string;
321	    workspaceId: string;
322	    taskRepoUrl: string;
323	    taskBranch: string;
324	    taskBaseBranch: string;
325	    taskRepoBaseBranch: string;
326	    mgmtRepoUrl: string;
327	    implementationModel: string;
328	    resultPath: string;
329	    workspaceLocalPath: string;
330	    /**
331	     * Briefing kind to dispatch with. Defaults to "impl" (fresh implementation or
332	     * blocked-recovery). "fix" → respond-to-review review-fixes mode.
333	     * "rebase" → respond-to-review conflict-resolution mode.
334	     */
335	    kind?: "impl" | "fix" | "rebase";
336	    /**
337	     * Implementation PR URL — passed to fix/rebase dispatches.
338	     */
339	    prUrl?: string;
340	    /**
341	     * The specific GitHub review event URL the fix agent should target.
342	     * Extracted by the caller from the most recent `reviewer_complete` log
343	     * entry. Set only for kind === "fix".
344	     */
345	    reviewUrl?: string;
346	  }) {
347	    const { task, featureId, workspaceId, taskRepoUrl, taskBranch, taskBaseBranch,
348	            taskRepoBaseBranch, mgmtRepoUrl, implementationModel, resultPath,
349	            workspaceLocalPath, kind = "impl", prUrl, reviewUrl } = opts;
350	
351	    const handle = randomUUID();
352	    const nonce = randomUUID();
353	    const callbackUrl = ports.broker.getCallbackUrl() ?? "";
354	
355	    const execInput: ExecutorPortInput = {
356	      taskId: task.id,
357	      featureId,
358	      workspaceId,
359	      handle,
360	      taskRepoUrl,
361	      taskRepoBranch: taskBranch,
362	      taskBaseBranch,
363	      taskRepoBaseBranch,
364	      executorWorkdir: join(workspacesRoot, `exec-${handle}`),
365	      mgmtRepoUrl,
366	      resultPath,
367	      budgetTokens: config.budget.max_tokens_per_task,
368	      implementationModel,
369	      sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
370	      githubToken,
371	      callbackUrl,
372	      nonce,
373	      // Broker `HandleKind` is decoupled from the orchestrator-internal `kind`
374	      // concept used for briefing routing. The reap loop branches:
375	      //   - kind="impl"      → dispatchExecutorResult (writes terminal_status to YAML)
376	      //   - kind="review-fix"→ emits review_dispatch_complete event ONLY (no YAML write)
377	      //   - kind="review"    → dispatchReviewResult
378	      //   - kind="rebase"    → conflict_state write
379	      // The fix agent's result has terminal_status: in_review|blocked and MUST
380	      // be written to YAML — so fix dispatches register as broker kind "impl"
381	      // (default). Only "rebase" needs an explicit override.
382	      //
383	      // Renaming the orchestrator-internal "fix" → ABI "review-fix" would route
384	      // fix results to the lightweight event branch and silently drop the YAML
385	      // write. Keep the abstractions separate.
386	      ...(kind === "rebase" ? { kind: "rebase" as const } : {}),
387	    };
388	
389	    const extraEnv: Record<string, string> = {
390	      TASK_BRANCH: taskBranch,
391	      MAX_TURNS: String(config.budget.max_iterations),
392	      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
393	      KIND: kind,
394	      ...(prUrl && (kind === "fix" || kind === "rebase") ? { IMPL_PR_URL: prUrl } : {}),
395	      // MODE + REVIEW_URL for respond-to-review dispatch.
396	      // Fix dispatch → review-fixes mode + the specific review's URL.
397	      // Rebase dispatch → conflict-resolution mode (no review URL needed).
398	      ...(kind === "fix"    ? { MODE: "review-fixes",       ...(reviewUrl ? { REVIEW_URL: reviewUrl } : {}) } : {}),
399	      ...(kind === "rebase" ? { MODE: "conflict-resolution" } : {}),
400	    };
401	
402	    const adapter =
403	      runtimeProfile === "local-docker"
404	        ? new (await import("./adapters/executor/claude-docker-run.js")).ClaudeDockerRunAdapter({
405	            broker: ports.broker,
406	            extraEnv,
407	            workspacesDir: workspacesRoot,
408	          })
409	        : new SubProcessAdapter({
410	            broker: ports.broker,
411	            executorBinPath: resolvedExecutorBinPath,
412	            extraEnv,
413	            workspacesDir: workspacesRoot,
414	          });
415	
416	    return adapter.submit(execInput);
417	  }
