477	  // ── Claim step: scan ready tasks, claim + spawn executor ─────────────────
478	  async function claimStep(
479	    haltedUrls: Set<string>,
480	    failedFeatureBranchMap: Map<string, Set<string>>,
481	  ): Promise<{ outcome: CycleOutcome; pulledWorkspaceRoots: string[] }> {
482	    const pulledWorkspaceRoots: string[] = [];
483	
484	    for (const watchUrl of config.watches) {
485	      if (haltedUrls.has(watchUrl)) continue;
486	
487	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
488	      pulledWorkspaceRoots.push(workspaceLocalPath);
489	
490	      if (!existsSync(workspaceLocalPath)) {
491	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
492	        continue;
493	      }
494	
495	      let eligibleTasks;
496	      try {
497	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
498	      } catch (e) {
499	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
500	        continue;
501	      }
502	
503	      if (eligibleTasks.length === 0) {
504	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
505	        continue;
506	      }
507	
508	      for (const { task, featureId } of eligibleTasks) {
509	        if (failedFeatureBranchMap.get(workspaceLocalPath)?.has(featureId)) {
510	          emit({ type: "task_skipped_feature_branch_failed", task_id: task.id, feature_id: featureId });
511	          continue;
512	        }
513	
514	        const claimResult = await claimTask({
515	          workspaceRoot: workspaceLocalPath,
516	          taskId: task.id,
517	          featureId,
518	          gitAuthorEmail,
519	          gitAuthorName,
520	          sshKeyPath,
521	          jitterMaxSeconds: config.jitter_max_seconds,
522	          // Task branches are seeded from and target the feature branch, not
523	          // the base branch — task PRs collect into the feature branch before
524	          // the Handoff Trigger merges the feature branch into the base.
525	          baseBranch: featureBranchName(featureId),
526	        });
527	
528	        const taskBranch = taskBranchName(featureId, task.id);
529	
530	        if (!claimResult.won) {
531	          if (claimResult.reason !== "branch_blocked_recovery") {
532	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
533	            continue;
534	          }
535	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
536	        } else {
537	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
538	        }
539	
540	        // ── Open management-repo PR ─────────────────────────────────────────
541	        if (githubToken) {
542	          try {
543	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
544	            await openWorkspacePr({
545	              workspaceRoot: workspaceLocalPath,
546	              featureId,
547	              taskId: task.id,
548	              branch: taskBranch,
549	              // Task PRs target the feature branch so all task changes collect
550	              // there before the Handoff Trigger merges to the base branch (T8).
551	              baseBranch: featureBranchName(featureId),
552	              githubToken,
553	              repoOwner: mgmtCoords.owner,
554	              repoName: mgmtCoords.repo,
555	              gitAuthorEmail,
556	              gitAuthorName,
557	              sshKeyPath,
558	            });
559	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
560	          } catch (e) {
561	            const stderr = (e as { stderr?: Buffer | string }).stderr;
562	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
563	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
564	          }
565	        }
566	
567	        // ── Resolve model + task repo ───────────────────────────────────────
568	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
569	          resolveTaskContext(workspaceLocalPath, featureId, task);
570	
571	        // ── RAG pre-flight ──────────────────────────────────────────────────
572	        const mcpRagUrl = process.env.MCP_RAG_URL;
573	        const workspaceYaml = parseYaml(
574	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
575	        ) as { workspace_id: string };
576	        const ragQuery = `${task.title} ${featureId}`;
577	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
578	
579	        try {
580	          writeRagPreFlight(
581	            workspaceLocalPath,
582	            featureId,
583	            task.id,
584	            taskBranch,
585	            gitAuthorEmail,
586	            gitAuthorName,
587	            sshKeyPath,
588	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
589	          );
590	        } catch (e) {
591	          const details = String(e);
592	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
593	          mutateTaskYaml({
594	            workspaceRoot: workspaceLocalPath,
595	            featureId,
596	            taskId: task.id,
597	            taskBranch,
598	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
599	            gitAuthorEmail,
600	            gitAuthorName,
601	            sshKeyPath,
602	          });
603	          continue;
604	        }
605	
606	
607	        // ── Submit executor (async — T6) ────────────────────────────────────
608	        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
609	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
610	        const execHandle = await buildAndSubmitExecutor({
611	          task, featureId, workspaceId: workspaceYaml.workspace_id,
612	          taskRepoUrl, taskBranch, taskBaseBranch: featureBranchName(featureId), taskRepoBaseBranch: taskBaseBranch,
613	          mgmtRepoUrl: mgmtCoords.repoUrl, implementationModel,
614	          resultPath, workspaceLocalPath,
615	        });
616	
617	        // Persist handle to task YAML for broker crash-recovery reconciliation.
618	        try {
619	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
620	        } catch (e) {
621	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
622	        }
623	
624	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
625	        if (runtimeProfile === "local-docker") dockerInFlight++;
626	        return { outcome: "ran_task", pulledWorkspaceRoots };
627	      }
628	    }
629	    return { outcome: "idle", pulledWorkspaceRoots };
630	  }
